previewCss:
.darma-loader-darma-b15-binary-tree-grow { --accent: var(--loader-color, #059669); --accent-2: var(--loader-secondary-color, #a7f3d0); width: var(--loader-size, 128px); height: calc(var(--loader-size, 128px) * .74); position: relative; }
.darma-loader-darma-b15-binary-tree-grow span { position: absolute; width: 13%; height: 17%; border-radius: 50%; background: radial-gradient(circle at 36% 32%, var(--accent-2), var(--accent)); transform: scale(0); animation: darma-loader-darma-b15-binary-tree-grow-tree-node calc(var(--loader-speed, 1s) * 3) ease-out infinite; }
.darma-loader-darma-b15-binary-tree-grow span::before { content: ''; position: absolute; left: 42%; bottom: 96%; width: calc(var(--loader-size, 128px) * .016); height: calc(var(--loader-size, 128px) * .19); border-radius: 2px; background: color-mix(in srgb, var(--accent) 45%, transparent); transform-origin: 50% 100%; transform: rotate(var(--tilt, 0deg)); }
.darma-loader-darma-b15-binary-tree-grow span:nth-of-type(1) { left: 43.5%; top: 2%; }
.darma-loader-darma-b15-binary-tree-grow span:nth-of-type(1)::before { display: none; }
.darma-loader-darma-b15-binary-tree-grow span:nth-of-type(2) { left: 21%; top: 40%; --tilt: 38deg; animation-delay: calc(var(--loader-speed, 1s) * .28); }
.darma-loader-darma-b15-binary-tree-grow span:nth-of-type(3) { left: 66%; top: 40%; --tilt: -38deg; animation-delay: calc(var(--loader-speed, 1s) * .28); }
.darma-loader-darma-b15-binary-tree-grow span:nth-of-type(4) { left: 6%; top: 78%; --tilt: 30deg; animation-delay: calc(var(--loader-speed, 1s) * .56); }
.darma-loader-darma-b15-binary-tree-grow span:nth-of-type(5) { left: 32%; top: 78%; --tilt: -30deg; animation-delay: calc(var(--loader-speed, 1s) * .56); }
.darma-loader-darma-b15-binary-tree-grow span:nth-of-type(6) { left: 55%; top: 78%; --tilt: 30deg; animation-delay: calc(var(--loader-speed, 1s) * .84); }
.darma-loader-darma-b15-binary-tree-grow span:nth-of-type(7) { left: 81%; top: 78%; --tilt: -30deg; animation-delay: calc(var(--loader-speed, 1s) * .84); }
@keyframes darma-loader-darma-b15-binary-tree-grow-tree-node { 0%, 4% { transform: scale(0); opacity: 0; } 22%, 72% { transform: scale(1); opacity: 1; } 90%, 100% { transform: scale(0); opacity: 0; } }

